import { useCallback, useEffect, useMemo, useState } from 'react';
import { useLocation } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import AdminLayout from '../../components/layout/AdminLayout';
import DataTable from '../../components/ui/DataTable';
import Modal from '../../components/ui/Modal';
import { listResource, getResource, updateResource } from '../../api/adminApi';

const STATUS_OPTIONS = ['pending', 'paid', 'processing', 'shipped', 'delivered', 'cancelled', 'refunded'];
const PAYMENT_STATUS_OPTIONS = ['unpaid', 'paid', 'failed', 'refunded'];

function escapeHtml(value) {
  return String(value ?? '').replace(/[&<>"']/g, (c) => (
    { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]
  ));
}

function formatAddress(shippingAddressJson) {
  if (!shippingAddressJson) return '';
  try {
    const a = typeof shippingAddressJson === 'string' ? JSON.parse(shippingAddressJson) : shippingAddressJson;
    return [a.governorate, a.area, a.block && `Block ${a.block}`, a.street].filter(Boolean).join(', ');
  } catch {
    return '';
  }
}

const BRAND = {
  pink: '#DE317C',
  pinkLight: '#F5639A',
  pinkPale: '#FDEBF0',
  gold: '#DBAB2F',
  goldPale: '#FEF0D0',
  espresso: '#3b2320',
  espressoSoft: '#8a6a66',
  linen: '#F8F2EC',
  green: '#1f8a4c',
  greenPale: '#e7f6ec',
  red: '#DF3033',
  redPale: '#FDEAE8',
};

// Order/payment statuses shown bilingually on the invoice, independent of
// the admin's current UI language — the printed document always carries
// both, since it's meant to be handed to (or emailed to) the customer.
const STATUS_AR = {
  pending: 'قيد الانتظار', paid: 'مدفوع', processing: 'قيد التجهيز', shipped: 'تم الشحن',
  delivered: 'تم التسليم', cancelled: 'ملغي', refunded: 'مسترد',
};
const PAYMENT_AR = { unpaid: 'غير مدفوع', paid: 'مدفوع', failed: 'فشل', refunded: 'مسترد' };

const STATUS_COLORS = {
  pending: { fg: BRAND.gold, bg: BRAND.goldPale },
  processing: { fg: BRAND.gold, bg: BRAND.goldPale },
  shipped: { fg: BRAND.pink, bg: BRAND.pinkPale },
  paid: { fg: BRAND.green, bg: BRAND.greenPale },
  delivered: { fg: BRAND.green, bg: BRAND.greenPale },
  cancelled: { fg: BRAND.red, bg: BRAND.redPale },
  refunded: { fg: BRAND.red, bg: BRAND.redPale },
  failed: { fg: BRAND.red, bg: BRAND.redPale },
  unpaid: { fg: BRAND.espressoSoft, bg: '#f1e9e6' },
};

// Merge both status-label maps: 'paid' / 'refunded' appear in each with the
// same Arabic wording, so one lookup covers order status and payment status.
const STATUS_LABEL_AR = { ...STATUS_AR, ...PAYMENT_AR };

function statusBadge(status) {
  const c = STATUS_COLORS[status] || { fg: BRAND.espressoSoft, bg: '#f1e9e6' };
  const ar = STATUS_LABEL_AR[status];
  return `<span class="badge" style="color:${c.fg};background:${c.bg};">${escapeHtml(status || '—')}${ar ? `<span class="ar">${escapeHtml(ar)}</span>` : ''}</span>`;
}

function money(amount, currency) {
  return `${Number(amount || 0).toFixed(3)} ${escapeHtml(currency || 'KWD')}`;
}

// Embedded as a data: URI (not fetched from /logo-mark.png) so the invoice popup never
// races a network image load against window.print() -- it renders correctly even
// offline or on a flaky connection.
const LOGO_DATA_URI = 'data:image/png;base64,';
const LOGO_URL = () => LOGO_DATA_URI;

// Shared stylesheet for both the single-order invoice and the bulk order-list
// print-out, so a "Print" from anywhere on this page carries the same brand
// header and typography rather than the browser's bare default rendering.
