function printHtml(title, bodyHtml) {
  const win = window.open('', '_blank', 'width=900,height=1000');
  if (!win) return;
  win.document.write(`<!doctype html>
<html>
<head>
<meta charset="utf-8" />
<title>${escapeHtml(title)}</title>
<style>${invoiceStyles()}</style>
</head>
<body><div class="sheet">${bodyHtml}</div></body>
</html>`);
  win.document.close();
  win.focus();
  // Wait for the window to finish loading (including the logo image) before
  // printing — calling print() right after document.write() races the
  // image request and can produce a print-out with a missing logo. Fall
  // back to a short timeout in case 'load' never fires (e.g. a blocked
  // image request), so printing still happens either way.
  let printed = false;
  const doPrint = () => {
    if (printed) return;
    printed = true;
    win.print();
  };
  win.addEventListener('load', doPrint);
  setTimeout(doPrint, 1200);
}

function invoiceHeader(docTitleEn, docTitleAr, number, dateStr) {
  return `
    <div class="header">
      <div class="brand">
        <img src="${escapeHtml(LOGO_URL())}" alt="Make Down" />
        <p class="brand-name">Make Down<span class="ar">ميك داون</span></p>
      </div>
      <div class="doc-meta">
        <p class="doc-title">${escapeHtml(docTitleEn)}<span class="ar">${escapeHtml(docTitleAr)}</span></p>
        <p class="doc-number">${escapeHtml(number)}</p>
        <p class="doc-date">${escapeHtml(dateStr)}</p>
      </div>
    </div>`;
}

function printList(rowsForPrint, listTitleEn, listTitleAr) {
  const rowsHtml = rowsForPrint
    .map(
      (r) => `<tr>
        <td>${escapeHtml(r.order_number)}</td>
        <td>${escapeHtml(r.user_name || r.guest_name || 'Guest')}</td>
        <td>${statusBadge(r.status)}</td>
        <td>${statusBadge(r.payment_status)}</td>
        <td class="end">${money(r.grand_total, r.currency)}</td>
        <td>${escapeHtml(new Date(r.created_at).toLocaleString())}</td>
      </tr>`
    )
    .join('');
  const body = `
    ${invoiceHeader(listTitleEn, listTitleAr, `${rowsForPrint.length} order(s)`, new Date().toLocaleString())}
    <table>
      <thead>
        <tr>
          <th>Order # <span class="ar">رقم الطلب</span></th>
          <th>Customer <span class="ar">العميل</span></th>
          <th>Status <span class="ar">الحالة</span></th>
          <th>Payment <span class="ar">الدفع</span></th>
          <th class="end">Total <span class="ar">الإجمالي</span></th>
          <th>Date <span class="ar">التاريخ</span></th>
        </tr>
      </thead>
      <tbody>${rowsHtml}</tbody>
    </table>
    <div class="footer">
      <p class="thanks">Make Down<span class="ar">ميك داون</span></p>
      <p class="note">Computer-generated report.<span class="ar">تقرير مُصدر إلكترونياً.</span></p>
    </div>`;
  printHtml(listTitleEn, body);
}

function buildInvoiceBody(order) {
  const items = order.items || [];
  const customerName = order.user_name || order.guest_name || 'Guest';
  const email = order.user_email || order.guest_email || '';
  const phone = order.guest_phone || '';
  const address = formatAddress(order.shipping_address_json);

  const itemsHtml = items
    .map(
      (item) => `<tr>
        <td>${escapeHtml(item.product_name_snapshot)}</td>
        <td class="center">${escapeHtml(item.quantity)}</td>
        <td class="end">${money(item.unit_price, order.currency)}</td>
        <td class="end">${money(item.line_total, order.currency)}</td>
      </tr>`
    )
    .join('');

  const discount = Number(order.discount_total || 0);
  const discountRow =
    discount > 0
      ? `<div class="totals-row discount">
           <span class="label">Discount${order.coupon_code ? ` (${escapeHtml(order.coupon_code)})` : ''}<span class="ar">الخصم</span></span>
           <span>-${money(discount, order.currency)}</span>
         </div>`
      : '';

  return `
    ${invoiceHeader('INVOICE', 'فاتورة', `#${order.order_number}`, new Date(order.created_at).toLocaleString())}

    <div class="info-grid">
      <div class="info-card">
        <p class="info-title">Bill To<span class="ar">إلى</span></p>
        <p class="info-line strong">${escapeHtml(customerName)}</p>
        ${email ? `<p class="info-line">${escapeHtml(email)}</p>` : ''}
        ${phone ? `<p class="info-line">${escapeHtml(phone)}</p>` : ''}
        ${address ? `<p class="info-line">${escapeHtml(address)}</p>` : ''}
      </div>
      <div class="info-card">
        <p class="info-title">Order Details<span class="ar">تفاصيل الطلب</span></p>
        <div class="info-row"><span class="label">Status<span class="ar">الحالة</span></span>${statusBadge(order.status)}</div>
        <div class="info-row"><span class="label">Payment<span class="ar">الدفع</span></span>${statusBadge(order.payment_status)}</div>
        ${order.payment_method ? `<div class="info-row"><span class="label">Method<span class="ar">طريقة الدفع</span></span><span>${escapeHtml(order.payment_method)}</span></div>` : ''}
      </div>
    </div>

    <h2 class="section-title">Items<span class="ar">المنتجات</span></h2>
    <table>
      <thead>
        <tr>
          <th>Item <span class="ar">المنتج</span></th>
          <th class="center">Qty <span class="ar">الكمية</span></th>
          <th class="end">Unit Price <span class="ar">سعر الوحدة</span></th>
          <th class="end">Total <span class="ar">الإجمالي</span></th>
        </tr>
      </thead>
      <tbody>${itemsHtml}</tbody>
    </table>

    <div class="totals">
      <div class="totals-row"><span class="label">Subtotal<span class="ar">المجموع الفرعي</span></span><span>${money(order.subtotal, order.currency)}</span></div>
      ${discountRow}
      <div class="totals-row"><span class="label">Delivery<span class="ar">التوصيل</span></span><span>${money(order.shipping_total, order.currency)}</span></div>
      <div class="totals-row grand"><span class="label">Grand Total<span class="ar">الإجمالي الكلي</span></span><span>${money(order.grand_total, order.currency)}</span></div>
    </div>

    <div class="footer">
      <p class="thanks">Thank you for shopping with Make Down!<span class="ar">شكراً لتسوقك مع ميك داون!</span></p>
      <p class="note">This is a computer-generated invoice.<span class="ar">هذه فاتورة مُصدرة إلكترونياً.</span></p>
    </div>`;
}

function printOrder(order) {
  printHtml(`Invoice ${order.order_number}`, buildInvoiceBody(order));
}

export default function OrdersPage() {
  const { t } = useTranslation();
  const location = useLocation();
  const isGuest = location.pathname.startsWith('/orders/guest');
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(true);
  const [viewing, setViewing] = useState(null);
  const [open, setOpen] = useState(false);

  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [paymentFilter, setPaymentFilter] = useState('');

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const params = { pageSize: 100 };
      if (isGuest) params.guest = '1';
      if (statusFilter) params.status = statusFilter;
      if (paymentFilter) params.payment_status = paymentFilter;
      const result = await listResource('/admin/orders', params);
      setRows(result.rows || []);
    } finally {
      setLoading(false);
    }
  }, [isGuest, statusFilter, paymentFilter]);

  useEffect(() => {
    load();
  }, [load]);

  const filteredRows = useMemo(() => {
    const term = search.trim().toLowerCase();
    if (!term) return rows;
    return rows.filter((r) => {
      const haystack = [
        r.order_number,
        r.user_name,
        r.guest_name,
        r.user_email,
        r.guest_email,
        r.guest_phone,
      ]
        .filter(Boolean)
        .join(' ')
        .toLowerCase();
      return haystack.includes(term);
    });
  }, [rows, search]);

  const view = async (row) => {
    const detail = await getResource(`/admin/orders/${row.id}`);
    setViewing(detail);
    setOpen(true);
  };

  const changeStatus = async (status) => {
    await updateResource(`/admin/orders/${viewing.id}`, { status });
    const detail = await getResource(`/admin/orders/${viewing.id}`);
    setViewing(detail);
    load();
  };

  const printRow = async (row) => {
    const detail = await getResource(`/admin/orders/${row.id}`);
    printOrder(detail);
  };

  return (
    <AdminLayout title={isGuest ? t('orders.guestTitle') : t('orders.title')}>
      <div className="mb-4 flex flex-wrap items-center gap-3">
        <input
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          placeholder={t('orders.searchPlaceholder')}
          className="w-full max-w-xs rounded-xl border border-linen-300 px-3.5 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-carissma-400"
        />
        <select
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value)}
          className="rounded-xl border border-linen-300 px-3.5 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-carissma-400"
        >
          <option value="">{t('orders.allStatuses')}</option>
          {STATUS_OPTIONS.map((s) => (
            <option key={s} value={s}>{s}</option>
          ))}
        </select>
        <select
          value={paymentFilter}
          onChange={(e) => setPaymentFilter(e.target.value)}
          className="rounded-xl border border-linen-300 px-3.5 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-carissma-400"
        >
          <option value="">{t('orders.allPaymentStatuses')}</option>
          {PAYMENT_STATUS_OPTIONS.map((s) => (
            <option key={s} value={s}>{s}</option>
          ))}
        </select>

        <button
          type="button"
          onClick={() => printList(filteredRows, isGuest ? t('orders.guestTitle') : t('orders.title'), isGuest ? 'طلبات الزوار' : 'الطلبات')}
          className="ms-auto rounded-xl border border-linen-300 bg-white px-4 py-2.5 text-sm font-semibold text-espresso-800 hover:bg-linen-50"
        >
          {t('orders.print')}
        </button>
      </div>

      <DataTable
        loading={loading}
        rows={filteredRows}
        columns={[
          { key: 'order_number', label: t('orders.orderNumber') },
          { key: 'user_name', label: t('orders.customer'), render: (r) => r.user_name || r.guest_name || t('orders.guest') },
          {
            key: 'address',
            label: t('orders.address'),
            render: (r) => (
              <span className="block max-w-[220px] truncate" title={formatAddress(r.shipping_address_json)}>
                {formatAddress(r.shipping_address_json) || '—'}
              </span>
            ),
          },
          { key: 'status', label: t('common.status') },
          { key: 'payment_status', label: t('orders.payment') },
          { key: 'grand_total', label: t('orders.total'), render: (r) => `${Number(r.grand_total).toFixed(3)} ${r.currency || 'KWD'}` },
          { key: 'created_at', label: t('orders.date'), render: (r) => new Date(r.created_at).toLocaleString() },
        ]}
        onEdit={view}
        onPrint={printRow}
      />

      <Modal open={open} title={viewing ? t('orders.orderTitle', { number: viewing.order_number }) : ''} onClose={() => setOpen(false)}>
        {viewing && (
          <div className="space-y-4 text-sm">
            <p>
              <span className="font-medium text-espresso-700">{t('orders.customer')}:</span>{' '}
              {viewing.user_name || viewing.guest_name || t('orders.guest')} ({viewing.user_email || viewing.guest_email})
            </p>
            <label className="block">
              <span className="mb-1.5 block text-sm font-medium text-espresso-800">{t('common.status')}</span>
              <select
                value={viewing.status}
                onChange={(e) => changeStatus(e.target.value)}
                className="w-full rounded-xl border border-linen-300 px-3 py-2.5 text-sm"
              >
                {STATUS_OPTIONS.map((s) => (
                  <option key={s} value={s}>{s}</option>
                ))}
              </select>
            </label>
            <div className="rounded-xl border border-linen-200">
              {(viewing.items || []).map((item) => (
                <div key={item.id} className="flex justify-between border-b border-linen-100 px-4 py-2 last:border-0">
                  <span>{item.product_name_snapshot} × {item.quantity}</span>
                  <span>{item.line_total} KWD</span>
                </div>
              ))}
            </div>
            <div className="flex items-center justify-between">
              <button
                type="button"
                onClick={() => printOrder(viewing)}
                className="rounded-xl border border-linen-300 bg-white px-4 py-2 text-sm font-semibold text-espresso-800 hover:bg-linen-50"
              >
                {t('orders.print')}
              </button>
              <p className="text-end font-semibold text-espresso-900">{t('orders.total2', { amount: viewing.grand_total })}</p>
            </div>
          </div>
        )}
      </Modal>
    </AdminLayout>
  );
}
